//! gobwire against Go's encoding/gob, both directions, over the corpus in `fixtures/gob/`
//! (generated by `reference/dump/gob`).
//!
//! * **Go → Rust.** Every stream Go wrote is decoded into the Rust mirror of the Go type Go
//!   decoded it into, and must yield what Go's decoder yielded — or fail where Go failed.
//! * **Wire.** Every stream decodes dynamically into exactly what Go sent.
//! * **Rust → Go.** What Rust decoded is re-encoded by Rust and handed back to Go, which must
//!   decode it into the same values it decoded from its own stream.
//!
//! Where Rust and Go deliberately differ, the case is listed in `DIVERGENCES` with the reason,
//! and the test asserts the divergence rather than skipping the case.

mod common;

use std::collections::HashMap;

use common::{Case, cases, decode_typed, for_each_value, go_echo, read, render, render_typed};
use gobwire::{BinaryBytes, Complex, Dynamic, Encode, Encoder, GoTime, Gob, GobBytes, Interface};
use serde_json::Value as Json;

// ─── Rust mirrors of reference/dump/gob's types ────────────────────────────────────────────

