macro_rules! one_field {
    ($($name:ident: $t:ty),*) => {$(
        #[derive(Gob, Debug, Default, Clone, PartialEq)]
        struct $name {
            n: $t,
        }
    )*};
}

one_field!(
    Ints: i64,
    Uints: u64,
    Strs: String,
    Floats: f64,
    IntSlice: Vec<i64>,
    IntArr: [i64; 1],
    StrMap: HashMap<String, i64>,
    IntMap: HashMap<i64, i64>,
    IfaceField: Option<Interface>,
    StructField: Inner
);

