// ─── the harness ───────────────────────────────────────────────────────────────────────────

/// What Rust made of a case: renderings of the decoded values, and the Rust re-encoding of them
/// as one stream — or the decode error.
struct Outcome {
    rendered: Vec<Json>,
    reencoded: Vec<u8>,
}

fn typed<T: gobwire::Decode + Encode + Default>(case: &Case) -> gobwire::Result<Outcome> {
    let values = decode_typed::<T>(case)?;
    let mut enc = Encoder::new();
    let mut reencoded = Vec::new();
    for v in &values {
        enc.encode_into(v, &mut reencoded)?;
    }
    Ok(Outcome {
        rendered: values.iter().map(|v| render_typed(v)).collect(),
        reencoded,
    })
}

fn run(case: &Case) -> gobwire::Result<Outcome> {
    match case.decode_as.as_str() {
        "Scalars" => typed::<Scalars>(case),
        "Inner" => typed::<Inner>(case),
        "*Inner" => typed::<Option<Inner>>(case),
        "Zeros" => typed::<Zeros>(case),
        "Nested" => typed::<Nested>(case),
        "Ifaces" => typed::<Ifaces>(case),
        "Marshalers" => typed::<Marshalers>(case),
        "Recursive" => typed::<Recursive>(case),
        "Wide" => typed::<Wide>(case),
        "WideNoNils" => typed::<WideNoNils>(case),
        "Narrow" => typed::<Narrow>(case),
        "Small" => typed::<Small>(case),
        "Big" => typed::<Big>(case),
        "ArrSmall" => typed::<ArrSmall>(case),
        "U16s" => typed::<U16s>(case),
        "U64s" => typed::<U64s>(case),
        "[]Unrelated" => typed::<Vec<Unrelated>>(case),
        "ArrBig" => typed::<ArrBig>(case),
        "Unrelated" => typed::<Unrelated>(case),
        "Ints" => typed::<Ints>(case),
        "Uints" => typed::<Uints>(case),
        "Strs" => typed::<Strs>(case),
        "Floats" => typed::<Floats>(case),
        "IntSlice" => typed::<IntSlice>(case),
        "IntArr" => typed::<IntArr>(case),
        "StrMap" => typed::<StrMap>(case),
        "IntMap" => typed::<IntMap>(case),
        "IfaceField" => typed::<IfaceField>(case),
        "StructField" => typed::<StructField>(case),
        "Post" => typed::<Post>(case),
        "Merge" => typed::<Merge>(case),
        "string" => typed::<String>(case),
        "int" => typed::<i64>(case),
        "[]string" => typed::<Vec<String>>(case),
        "map[string]int" => typed::<HashMap<String, i64>>(case),
        "any" => typed::<Option<Interface>>(case),
        "time.Time" => typed::<GoTime>(case),
        other => panic!("no Rust mirror for Go type {other:?}; add one to go_parity.rs"),
    }
}

/// Cases where Rust and Go deliberately or unavoidably differ, and how.
enum Divergence {
    /// Go's decoder fails on its own stream; Rust decodes it.
    GoDecoderBug,
    /// Rust decodes as Go does, but a Rust re-encoding cannot express the named field, so Go
    /// reads back a different value there.
    Reencode(&'static str),
    /// Go itself does not round-trip the named field: Go decoding what Go would re-encode yields
    /// a different value. Rust writes Go's bytes, so Go drifts the same way reading them.
    GoNotIdempotent(&'static str),
}

fn divergence(name: &str) -> Option<Divergence> {
    match name {
        // decode.go, ignoreInterface: skipping an interface that defines its concrete type
        // inline fails ("field numbers out of bounds"); skipping a nil interface reads a type
        // sequence that is not there. Rust skips both correctly.
        "skip_iface_inline_type" | "skip_nil_iface" => Some(Divergence::GoDecoderBug),
        // `ME map[string]int{}` is an empty non-nil map, which Go sends; a Rust HashMap cannot be
        // nil, so an empty one re-encodes as the nil a zero Go struct holds.
        "zeros" => Some(Divergence::Reencode("ME")),
        // time.go: MarshalBinary writes the seconds part of a negative offset signed and
        // UnmarshalBinary adds it back unsigned, so -01:00:01 comes back 256 s east, and again on
        // every further round trip.
        "marshalers" => Some(Divergence::GoNotIdempotent("TNeg")),
        _ => None,
    }
}

fn without(values: &[Json], field: &str) -> Vec<Json> {
    let mut out = values.to_vec();
    for v in &mut out {
        if let Some(o) = v.as_object_mut() {
            o.remove(field);
        }
    }
    out
}

#[test]
fn every_case_has_a_distinct_name_and_fixture() {
    let cases = cases();
    assert!(cases.len() >= 40, "corpus shrank to {}", cases.len());
    let mut names: Vec<_> = cases.iter().map(|c| &c.name).collect();
    names.sort();
    names.dedup();
    assert_eq!(names.len(), cases.len());
    for c in &cases {
        assert!(!read(&c.stream).is_empty(), "{}", c.name);
    }
}

/// Go → Rust, typed: Rust decodes what Go decoded, and fails where Go failed.
#[test]
fn typed_decode_matches_go() {
    let mut failures = Vec::new();
    for case in cases() {
        let outcome = run(&case);
        match (&case.error, outcome, divergence(&case.name)) {
            (Some(go_err), Ok(o), Some(Divergence::GoDecoderBug)) => {
                // Rust decodes where Go's skip is broken: check it got the fields it kept.
                assert_eq!(
                    o.rendered.len(),
                    1,
                    "{}: Go failed with {go_err}",
                    case.name
                );
            }
            (Some(go_err), Ok(o), _) => failures.push(format!(
                "{}: Go failed ({go_err}) but Rust decoded {:?}",
                case.name, o.rendered
            )),
            (None, Err(e), _) => failures.push(format!("{}: Rust failed: {e}", case.name)),
            (Some(_), Err(_), _) => {}
            (None, Ok(o), Some(Divergence::Reencode(field))) => {
                // Rendering goes through a Rust re-encoding, so the field is lost here too.
                assert_ne!(
                    o.rendered, case.decoded,
                    "{}: divergence no longer happens",
                    case.name
                );
                if o.rendered != without(&case.decoded, field) {
                    failures.push(format!("{}: beyond the {field} divergence", case.name));
                }
            }
            (None, Ok(o), _) => {
                if o.rendered != case.decoded {
                    failures.push(format!(
                        "{}:\n  go   {}\n  rust {}",
                        case.name,
                        Json::Array(case.decoded.clone()),
                        Json::Array(o.rendered)
                    ));
                }
            }
        }
    }
    assert!(
        failures.is_empty(),
        "{} of the corpus differ:\n{}",
        failures.len(),
        failures.join("\n")
    );
}

/// Wire: dynamic decoding sees exactly what Go sent.
#[test]
fn dynamic_decode_matches_the_wire() {
    let mut failures = Vec::new();
    for case in cases() {
        let mut rendered = Vec::new();
        let result = for_each_value(&read(&case.stream), |dec| {
            let d: Dynamic = dec.decode()?;
            rendered.push(render(&d.ty, &d.value));
            Ok(())
        });
        match (case.name.as_str(), result) {
            // A recursive type has no dynamic shape.
            ("recursive", Err(gobwire::Error::Unsupported(_))) => {}
            ("skip_wide", Err(gobwire::Error::Unsupported(_))) => {}
            (_, Err(e)) => failures.push(format!("{}: {e}", case.name)),
            (_, Ok(_)) if rendered != case.wire => failures.push(format!(
                "{}:\n  wire {}\n  rust {}",
                case.name,
                Json::Array(case.wire.clone()),
                Json::Array(rendered)
            )),
            _ => {}
        }
    }
    assert!(
        failures.is_empty(),
        "{} differ:\n{}",
        failures.len(),
        failures.join("\n")
    );
}

/// Rust → Go: Go decodes Rust's re-encoding into what it decoded from its own stream.
#[test]
fn go_decodes_what_rust_encodes() {
    let mut failures = Vec::new();
    let mut checked = 0;
    for case in cases() {
        if case.error.is_some() {
            continue;
        }
        let Ok(outcome) = run(&case) else { continue };
        let echo = go_echo(&case.decode_as, &outcome.reencoded, case.base.as_deref());
        checked += 1;
        if let Some(e) = &echo.error {
            failures.push(format!(
                "{}: Go could not decode Rust's stream: {e}",
                case.name
            ));
            continue;
        }
        match divergence(&case.name) {
            Some(Divergence::Reencode(field) | Divergence::GoNotIdempotent(field)) => {
                assert_ne!(
                    echo.decoded[0].get(field),
                    case.decoded[0].get(field),
                    "{}: the {field} divergence no longer happens",
                    case.name
                );
                if without(&echo.decoded, field) != without(&case.decoded, field) {
                    failures.push(format!("{}: beyond the {field} divergence", case.name));
                }
            }
            _ if echo.decoded != case.decoded => failures.push(format!(
                "{}:\n  go-from-go   {}\n  go-from-rust {}",
                case.name,
                Json::Array(case.decoded.clone()),
                Json::Array(echo.decoded)
            )),
            _ => {}
        }
    }
    assert!(checked >= 20, "only {checked} cases reached Go");
    assert!(
        failures.is_empty(),
        "{} differ:\n{}",
        failures.len(),
        failures.join("\n")
    );
}

/// Rust → Go, dynamic: a value held only dynamically re-encodes into something Go decodes into
/// the original Go type.
#[test]
fn go_decodes_dynamic_reencoding() {
    let mut failures = Vec::new();
    for case in cases() {
        if case.error.is_some() || case.base.is_some() {
            continue;
        }
        let mut enc = Encoder::new();
        let mut stream = Vec::new();
        let result = for_each_value(&read(&case.stream), |dec| {
            let d: Dynamic = dec.decode()?;
            enc.encode_into(&d, &mut stream)
        });
        if matches!(result, Err(gobwire::Error::Unsupported(_))) {
            continue;
        }
        result.unwrap();
        let echo = go_echo(&case.decode_as, &stream, None);
        if echo.error.is_some() || echo.decoded != case.decoded {
            failures.push(format!(
                "{}: {:?} {}",
                case.name,
                echo.error,
                Json::Array(echo.decoded)
            ));
        }
    }
    assert!(
        failures.is_empty(),
        "{} differ:\n{}",
        failures.len(),
        failures.join("\n")
    );
}

/// Go's skip bug is only reachable when a type is defined inside the skipped interface. This
/// encoder always defines types in messages of their own before the value, so Go can skip
/// anything Rust sends.
#[test]
fn go_can_skip_what_rust_sends() {
    let wide = WideNoNils {
        keep: "kept".into(),
        iface: Some(
            Interface::new(
                gobwire::names::STRING_ANY_MAP,
                &HashMap::from([("k".to_string(), Some(Interface::string("v")))]),
            )
            .unwrap(),
        ),
        last: 99,
        ..Default::default()
    };
    let nils = Wide {
        keep: "kept".into(),
        nils_iface: vec![None, Some(Interface::string("x"))],
        last: 99,
        ..Default::default()
    };
    for (label, stream) in [
        ("inline type", Encoder::new().encode(&wide).unwrap()),
        ("nil iface", Encoder::new().encode(&nils).unwrap()),
    ] {
        let echo = go_echo("Narrow", &stream, None);
        if label == "nil iface" {
            // The nil-interface bug is in Go's skip itself and no encoding avoids it.
            assert!(
                echo.error.is_some(),
                "{label}: Go's nil-interface skip bug is fixed; revisit"
            );
        } else {
            assert_eq!(echo.error, None, "{label}");
            assert_eq!(
                echo.decoded,
                vec![serde_json::json!({"Keep": "kept", "Last": 99})],
                "{label}"
            );
        }
    }
}
